    "body": "// Tiles protocol: links (https://dasl.ing/tp-link.html).\n//\n// A tile navigates itself, inside its own resources, and nothing else: it\n// cannot open a window, and a link to anywhere else does not load. What it\n// can do is ask the context that runs it to open a link. The context decides,\n// and opens it somewhere of its own: never in the tile.\n//\n// An ordinary link needs none of this: for `<a href=\"https://…\">` the runtime\n// asks on the tile's behalf when the user follows it (see shuttle.js). This\n// module is for asking from script.\n//\n//   const link = await import('/.well-known/web-tiles/link.js');\n//   const { opened } = await link.openLink('https://example.com/');\n\nconst UP = 'tiles-protocol-up-link-';\nconst DOWN = 'tiles-protocol-down-link-';\n// A context may ask its user first, which takes as long as it takes them. One\n// that never answers has not opened anything.\nconst ANSWER_MS = 30000;\n\nconst pending = new Map();\nlet counter = 0;\n\nwindow.addEventListener('message', (ev) => {\n  // Answers come from the context, which is our parent, and from no one else.\n  if (ev.source !== window.parent) return;\n  const { action, payload } = ev.data || {};\n  if (action !== `${DOWN}result` || !payload || typeof payload !== 'object') return;\n  const resolve = pending.get(payload.id);\n  if (!resolve) return;\n  pending.delete(payload.id);\n  resolve({ opened: payload.opened === true });\n});\n\n/**\n * Asks the context to open `url`, which has to be an absolute URL. Resolves\n * with `{ opened }`: whether the context says it opened it. It may refuse, or\n * ask the user, who may refuse; and where it does not answer at all, nothing\n * was opened.\n *\n * Rejects, with a TypeError, if `url` is not an absolute URL. A relative one\n * is a place inside the tile, which is the tile's own to go to and nothing a\n * context can open: asking for it is a mistake, and is not sent.\n */\nexport function openLink (url) {\n  let href;\n  try {\n    // No base: a relative URL does not parse.\n    href = new URL(String(url)).href;\n  }\n  catch {\n    return Promise.reject(new TypeError(`openLink() needs an absolute URL, and got ${JSON.stringify(String(url))}`));\n  }\n  const id = `l${++counter}`;\n  return new Promise((resolve) => {\n    pending.set(id, resolve);\n    setTimeout(() => {\n      if (pending.delete(id)) resolve({ opened: false });\n    }, ANSWER_MS);\n    window.parent.postMessage({ action: `${UP}open`, payload: { id, url: href } }, '*');\n  });\n}\n\n/**\n * The URL a click would follow out of the tile, or undefined: the `href` of\n * the link the event went through, when that link leads to another origin.\n * Links inside the tile, downloads, and `javascript:`, `blob:`, `data:` and\n * `about:` URLs are the tile's own business. The runtime calls this for a\n * tile's document; `origin` is the tile's.\n */\nexport function linkOut (ev, origin) {\n  for (const node of ev.composedPath()) {\n    if (node?.nodeType !== 1 || (node.localName !== 'a' && node.localName !== 'area')) continue;\n    const href = node.getAttribute('href') ?? node.getAttribute('xlink:href');\n    if (href === null || node.hasAttribute('download')) return;\n    let url;\n    try { url = new URL(href, node.baseURI); }\n    catch { return; }\n    if (url.origin === origin || ['javascript:', 'blob:', 'data:', 'about:'].includes(url.protocol)) return;\n    return url.href;\n  }\n}\n\n/**\n * Has `report(url)` called whenever the user follows a link out of `doc`,\n * instead of the navigation (which would not load anyway). A click the tile\n * has dealt with itself (`preventDefault()`) is left alone, as is anything\n * but a plain primary click.\n */\nexport function watchLinks (doc, origin, report) {\n  doc.addEventListener('click', (ev) => {\n    if (ev.defaultPrevented || ev.button !== 0) return;\n    const url = linkOut(ev, origin);\n    if (!url) return;\n    ev.preventDefault();\n    report(url);\n  });\n}\n"
