const ALPHABET = 'abcdefghijklmnopqrstuvwxyz'

function baseHost(): string {
  return (Deno.env.get('BASE_HOST') || 't.mu.social')
    .toLowerCase()
    .replace(/^\./, '')
}

/** Twenty random letters, unbiased: a label no one can guess or reuse. */
function randomLabel(): string {
  let out = ''
  while (out.length < 20) {
    for (const byte of crypto.getRandomValues(new Uint8Array(32))) {
      // 234 = 9 * 26: drop the bytes that would favour the first letters.
      if (byte < 234 && out.length < 20) out += ALPHABET[byte % 26]
    }
  }
  return out
}

/**
 * The host the visitor asked for. At the edge the Host header and the request
 * URL can carry an internal host, so both are tried, then CDN-Host, the
 * header Bunny puts the visitor's hostname in; whichever candidate belongs to
 * the base host wins. X-Forwarded-Host is not among them: Bunny never sets
 * it, so one that arrives is the client's own.
 */
function requestHost(req: Request, base: string): string {
  const candidates = [
    req.headers.get('host'),
    new URL(req.url).host,
    req.headers.get('cdn-host'),
  ]
  for (const candidate of candidates) {
    const host = (candidate || '').split(',')[0].trim().toLowerCase()
    const name = host.replace(/:\d+$/, '')
    if (name === base || name.endsWith(`.${base}`)) return host
  }
  return (candidates.find(Boolean) || '').toLowerCase()
}

/**
 * A file by its name, if it is one of the files: a plain lookup would also
 * answer for the names every object has (`constructor`, `toString`).
 */
function fileNamed(
  files: Record<string, {type: string; etag: string; body: string}>,
  name: string,
) {
  return Object.hasOwn(files, name) ? files[name] : undefined
}

function dead(
  status: number,
  text: string,
  extra: Record<string, string> = {},
) {
  return new Response(text, {
    status,
    headers: {
      ...DEAD_HEADERS,
      'content-type': 'text/plain; charset=utf-8',
      'cache-control': 'no-store',
      ...extra,
    },
  })
}

// What the expiries in one answer may come to. An answer whose headers are
// too large is given up on, by a browser (Chrome at 256 kB) and maybe by the
// CDN before it, whose limit is not known; and names cost more to expire
// than to send, so a jar can need far more than that. What does not fit goes
// with the answers to the requests that follow, which no longer bring what
// was expired. 16 kB is the base host's expiries for 180 short names: all of
// a page's credentialless jar in Chromium, in one answer.
const EXPIRIES = 16 * 1024

/**
 * Expires every cookie the request carried, for the base host and host-only:
 * whatever a tile managed to leave behind under our own names goes. Nothing
 * above the base host is touched. The widest first (Domain=<BASE_HOST>
 * reaches every tile origin and the loading host), and only as many as fit
 * in EXPIRIES bytes.
 */
function scrubCookies(req: Request, res: Response, base: string): Response {
  const names = new Set(
    (req.headers.get('cookie') || '')
      .split(';')
      .map(pair => pair.split('=')[0].trim())
      .filter(name => /^[\w!#$%&'*+.^`|~-]+$/.test(name)),
  )
  if (!names.size) return res
  const headers = new Headers(res.headers)
  const domain = base.replace(/:\d+$/, '')
  const gone = (name: string) =>
    `${name}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT`
  let room = EXPIRIES
  let sent = 0
  for (const expiry of [
    ...[...names].map(name => `${gone(name)}; Domain=${domain}`),
    ...[...names].map(gone),
  ]) {
    room -= expiry.length
    if (room < 0) break
    headers.append('set-cookie', expiry)
    sent++
  }
  // Says the scrub ran, and how many it sent, for when a CDN setting strips
  // the Set-Cookie lines.
  headers.set('x-tile-cookies-expired', String(sent))
  return new Response(res.body, {status: res.status, headers})
}

BunnySDK.net.http.serve((req: Request): Response => {
  return scrubCookies(req, respond(req), baseHost())
})

function respond(req: Request): Response {
  const base = baseHost()
  const url = new URL(req.url)
  const host = requestHost(req, base)
  const name = host.replace(/:\d+$/, '')
  const port = host.match(/:(\d+)$/)?.[1]

  if (name === `load.${base}`) {
    const origin = `${randomLabel()}.${base}${port ? `:${port}` : ''}`
    // Always https, except for a local run on *.localhost.
    const scheme = base.endsWith('localhost') ? 'http' : 'https'
    if (url.pathname.startsWith(DOCK_PATH)) {
      return dock(req, url, {base, host, port, scheme, origin})
    }
    return new Response(null, {
      status: 303,
      headers: {
        location: `${scheme}://${origin}${url.pathname}${url.search}`,
        'cache-control': 'no-store',
        'referrer-policy': 'no-referrer',
        'x-content-type-options': 'nosniff',
      },
    })
  }

  // The base host itself: the page native WebViews run a tile in.
  if (name === base) {
    if (url.pathname === HOST_PATH.slice(0, -1)) {
      return new Response(null, {
        status: 308,
        headers: {location: `${HOST_PATH}${url.search}`},
      })
    }
    const file = url.pathname.startsWith(HOST_PATH)
      ? fileNamed(
          HOST_FILES,
          url.pathname.slice(HOST_PATH.length) || 'index.html',
        )
      : undefined
    if (!file) return dead(404, 'Nothing here.')
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      return dead(405, 'Method not allowed.', {allow: 'GET, HEAD'})
    }
    return new Response(req.method === 'HEAD' ? null : file.body, {
      status: 200,
      headers: {
        ...HOST_HEADERS,
        // The page frames the dock, on the loading host, and nothing else
        // (any port, for local runs): the tile's origin is framed there.
        'content-security-policy': HOST_HEADERS[
          'content-security-policy'
        ].replace(
          '__FRAME_SRC__',
          `https://load.${base} http://load.${base}:*`,
        ),
        'content-type': file.type,
        etag: file.etag,
        'cache-control': 'no-cache',
      },
    })
  }

  // Only names this server mints are tile origins.
  const label = name.endsWith(`.${base}`)
    ? name.slice(0, -(base.length + 1))
    : ''
  if (!/^[a-z]{20}$/.test(label)) return dead(404, 'Not a tile origin.')

  if (url.pathname === WIPE_PATH) {
    return new Response('<!doctype html><title>Wiped</title>', {
      status: 200,
      headers: {...WIPE_HEADERS, 'content-type': 'text/html; charset=utf-8'},
    })
  }

  if (url.pathname.startsWith(RUNTIME_PATH)) {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      return dead(405, 'Method not allowed.', {allow: 'GET, HEAD'})
    }
    const file = fileNamed(
      FILES,
      url.pathname.slice(RUNTIME_PATH.length) || 'index.html',
    )
    if (file) {
      const headers = {
        ...RUNTIME_HEADERS,
        'content-type': file.type,
        etag: file.etag,
        // The runtime is small and must track releases: revalidate each time.
        'cache-control': 'no-cache',
      }
      if (req.headers.get('if-none-match') === file.etag) {
        return new Response(null, {status: 304, headers})
      }
      return new Response(req.method === 'HEAD' ? null : file.body, {
        status: 200,
        headers,
      })
    }
  }
  return dead(404, 'Not a tile resource.')
}

/**
 * The dock: the page, for one tile origin named in `?tile=`, with a policy
 * made for that origin; and its script. Only an origin of the shape this
 * server mints, on this port, is docked.
 */
function dock(
  req: Request,
  url: URL,
  {
    base,
    host,
    port,
    scheme,
    origin,
  }: {
    base: string
    host: string
    port?: string
    scheme: string
    origin: string
  },
): Response {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    return dead(405, 'Method not allowed.', {allow: 'GET, HEAD'})
  }
  const path = url.pathname.slice(DOCK_PATH.length) || 'index.html'
  const file = fileNamed(DOCK_FILES, path)
  if (!file) return dead(404, 'Not part of the dock.')
  let docked = origin
  if (path === 'index.html') {
    const asked = url.searchParams.getAll('tile')
    if (asked.length === 0) {
      return new Response(null, {
        status: 303,
        headers: {
          location: `${scheme}://${host}${DOCK_PATH}?tile=${encodeURIComponent(origin)}`,
          'cache-control': 'no-store',
          'referrer-policy': 'no-referrer',
          'x-content-type-options': 'nosniff',
        },
      })
    }
    const m =
      asked.length === 1
        ? asked[0].toLowerCase().match(/^([a-z]{20})\.(.+?)(?::(\d+))?$/)
        : null
    if (!m || m[2] !== base || m[3] !== port) {
      return dead(400, 'Not a tile origin.')
    }
    docked = `${m[1]}.${base}${port ? `:${port}` : ''}`
  }
  const headers: Record<string, string> = {
    ...DOCK_HEADERS,
    'content-type': file.type,
  }
  headers['content-security-policy'] = headers[
    'content-security-policy'
  ].replace(DOCK_ORIGIN, `${scheme}://${docked}`)
  return new Response(req.method === 'HEAD' ? null : file.body, {
    status: 200,
    headers,
  })
}
